INSERT OR IGNORE INTO testimonials (id, quote, author_name, author_location, author_initial, author_color_hex, is_published, display_order, created_at) VALUES ('test-01', 'The Halvyache Dagine for my first Makar Sankranti after marriage were so incredibly beautiful. Every relative asked where we got them. Ananya Tai understood our family''s traditional Pune style perfectly.', 'Ketaki Joshi', 'Pune (Kothrud) • Sankranti Bride', 'K', '#5b0218', 1, 0, '2026-10-28T15:03:24.389Z');
INSERT OR IGNORE INTO testimonials (id, quote, author_name, author_location, author_initial, author_color_hex, is_published, display_order, created_at) VALUES ('test-02', 'Ananya Tai created our Dohale Jevan floral jewellery matching my bottle green Paithani with gold zari. The mogra garland and haathphool were fresh until 9 PM. Absolutely magical.', 'Snehal Patil', 'Thane, Mumbai • Dohale Jevan', 'S', '#261900', 1, 1, '2026-10-28T15:03:24.389Z');
INSERT OR IGNORE INTO testimonials (id, quote, author_name, author_location, author_initial, author_color_hex, is_published, display_order, created_at) VALUES ('test-03', 'Booked bridal mehendi and fresh floral haathphool for my sister''s Haldi. The WhatsApp communication was seamless and the pieces arrived two days before — perfectly packed. Will order again.', 'Pooja Deshmukh', 'Nashik • Wedding Sibling', 'P', '#40000e', 1, 2, '2026-10-28T15:03:24.389Z');
