INSERT OR REPLACE INTO site_settings (id, key, value, updated_at) VALUES ('hero', 'hero', '{"badge":"MAHARASHTRIAN HERITAGE CRAFTSMANSHIP","title":"Ananya","titleEm":"Creations","subtitle":"Halvyache Dagine & Floral Jewellery","desc":"Handcrafted Maharashtrian ornaments for weddings, Sankranti, Haldi & Dohale Jevan. Each piece individually made to match your Nauvari & Paithani.","ctaPrimary":"WhatsApp Custom Order","ctaPrimaryText":"Hello Ananya Tai, I would like to enquire about a custom order","ctaSecondary":"Explore Collections","ctaSecondaryHref":"#collections","images":[{"src":"assets/images/img_01.png","alt":"Bridal Halvyache Dagine","cls":"hero-img--main"},{"src":"assets/images/img_02.png","alt":"Mogra Floral Jewellery","cls":"hero-img--top"},{"src":"assets/images/img_03.png","alt":"Kolhapuri Saaj","cls":"hero-img--bottom"}],"trust":["12+ Years Artisan","2,400+ Weddings","Worldwide Shipping","Custom Saree Match"]}', '2026-10-28T15:03:24.389Z');
