INSERT OR REPLACE INTO site_settings (id, key, value, updated_at) VALUES ('featured', 'featured', '{"badge":"विशेष निर्मिती","title":"Featured Creations","subtitle":"Handpicked best-sellers and seasonal specials — enquire via WhatsApp for live pricing and availability.","cta":"WhatsApp Enquiry"}', '2026-10-28T15:03:24.389Z');
INSERT OR REPLACE INTO site_settings (id, key, value, updated_at) VALUES ('occasions', 'occasions', '{"badge":"सण","title":"Special Occasions","subtitle":"Every Maharashtrian celebration deserves a perfectly curated jewellery set. We specialize in all sacred ceremonies.","items":[{"id":"occ-01","icon":"🌸","title":"Bridal Wedding","desc":"Complete bridal suites for the Maharashtrian Saptapadi"},{"id":"occ-02","icon":"🌼","title":"Haldi Ceremony","desc":"Turmeric-hued ornaments and fresh floral jewellery"},{"id":"occ-03","icon":"🌺","title":"Dohale Jevan","desc":"Baby shower jewellery and ceremonial sets"},{"id":"occ-04","icon":"⚫","title":"Makar Sankranti","desc":"Black & gold tilgul sets for the sesame harvest festival"},{"id":"occ-05","icon":"💛","title":"Sakharpuda","desc":"Engagement jewellery in traditional Maharashtrian style"},{"id":"occ-06","icon":"🌿","title":"Seemant / Godh Bharai","desc":"Auspicious baby shower ornaments and blessings"}]}', '2026-10-28T15:03:24.389Z');
INSERT OR REPLACE INTO site_settings (id, key, value, updated_at) VALUES ('custom', 'custom', '{"badge":"कस्टम ऑर्डर","title":"Custom Order Enquiry","subtitle":"Share your ceremony details and saree colour palette. We''ll handcraft jewellery that matches perfectly.","submit":"Submit Custom Enquiry & Open WhatsApp Chat","fields":{"name":{"label":"Full Name *","placeholder":"Your full name"},"whatsapp":{"label":"Mobile / WhatsApp Number *","placeholder":"+91 98765 43210"},"email":{"label":"Email Address","placeholder":"you@email.com"},"occasion":{"label":"Occasion / Ceremony Type *","placeholder":"Select occasion"},"date":{"label":"Ceremony / Delivery Date *"},"palette":{"label":"Saree Color & Fabric Palette (Optional)","placeholder":"e.g. Peacock Blue Paithani with gold zari border, Rani Pink, Haldi Yellow"},"notes":{"label":"Specific Design Requests / Notes","placeholder":"Tell us if you prefer fresh Mogra or artificial preserved flowers, special pieces, references…"}},"occasions":["Bridal Wedding","Haldi Ceremony","Dohale Jevan","Makar Sankranti","Sakharpuda","Seemant / Godh Bharai","Other"],"formIntro":"Hello Ananya Tai! I would like to place a custom order."}', '2026-10-28T15:03:24.389Z');
INSERT OR REPLACE INTO site_settings (id, key, value, updated_at) VALUES ('gallery', 'gallery', '{"badge":"हस्तकलेचा अल्बम","title":"Atelier Craft Gallery","subtitle":"Explore authentic photographs of our past handcrafted sets worn by Maharashtrian brides and families.","view":"View","tabs":[{"id":"tab-all","filter":"all","label":"All Works","active":true},{"id":"tab-floral","filter":"floral","label":"Floral Jewellery"},{"id":"tab-festive","filter":"festive","label":"Festive Ornaments"},{"id":"tab-bridal","filter":"bridal","label":"Bridal Embroidery"},{"id":"tab-decor","filter":"decor","label":"Decor & Hampers"}]}', '2026-10-28T15:03:24.389Z');
INSERT OR REPLACE INTO site_settings (id, key, value, updated_at) VALUES ('about', 'about', '{"badge":"THE ARTISAN BEHIND THE BRAND","title":"Where Maharashtrian Heritage","titleLine2":"Meets Heartfelt Craftsmanship.","paras":["Ananya Creations began over a decade ago in the peaceful cultural heart of Pune.","What began as handcrafted adornments for family weddings soon blossomed into a renowned atelier trusted by over 2,400 Maharashtrian families."],"pillars":[{"id":"pillar-01","title":"Zero Mass Production","desc":"Every order is created singly by hand with dedicated artisanal focus."},{"id":"pillar-02","title":"Exact Saree Pairing","desc":"Colours customized accurately to match your Nauvari and Paithani borders."},{"id":"pillar-03","title":"Punctual Muhurat Delivery","desc":"Guaranteed delivery timed precisely to your ceremony schedule."}],"stat":"12+ Years","statDesc":"Crafting heirlooms for over 2,400 Maharashtrian weddings and celebrations.","cta":"Speak with Smt. Ananya","ctaText":"Hello Smt. Ananya, I''d like to speak with you","portrait":"assets/images/artisan_portrait.png","portraitAlt":"Smt. Ananya Kulkarni – Master Artisan"}', '2026-10-28T15:03:24.389Z');
INSERT OR REPLACE INTO site_settings (id, key, value, updated_at) VALUES ('testimonials', 'testimonials', '{"badge":"आनंदी कुटुंबे","title":"Heartfelt Words from Our Brides & Families","subtitle":"Read genuine reviews from families who entrusted us with their sacred occasions."}', '2026-10-28T15:03:24.389Z');
INSERT OR REPLACE INTO site_settings (id, key, value, updated_at) VALUES ('faq', 'faq', '{"badge":"नेहमी विचारले जाणारे प्रश्न","title":"Frequently Asked Questions","subtitle":"Everything you need to know about preservation, courier delivery, and custom matching.","items":[{"id":"faq-01","q":"How do I preserve fresh floral jewellery before the event?","a":"Store in a cool, airtight container with a damp cloth. Keep refrigerated at 4°C. We send detailed preservation instructions with every fresh flower order."},{"id":"faq-02","q":"Do you ship Halvyache Dagine outside Maharashtra & abroad?","a":"Yes, we ship pan-India and internationally. Artificial/preserved pieces ship worldwide via insured courier. Fresh flower sets are only available within 200km of Pune."},{"id":"faq-03","q":"How much advance notice is required for custom orders?","a":"Standard custom orders require 15–21 days advance booking. Bridal suites require 30–45 days. For urgent orders, contact us on WhatsApp and we''ll advise on availability."},{"id":"faq-04","q":"Can you customize to match my specific Paithani saree blouse?","a":"Absolutely. Share clear photographs of your saree, especially the border, pallu and blouse fabric. We colour-match using natural dyes and gold wire to create a harmonious set."}]}', '2026-10-28T15:03:24.389Z');
INSERT OR REPLACE INTO site_settings (id, key, value, updated_at) VALUES ('contact', 'contact', '{"title":"Ananya Creations Boutique Atelier","tagline":"Handmade Maharashtrian Traditions","addressLabel":"Home Studio Location","address":"Mayur Colony, Kothrud, Pune, Maharashtra 411038","addressNote":"(In-person consultations available by prior WhatsApp appointment)","hoursLabel":"Atelier Hours","hours":"Monday – Saturday: 10:00 AM – 7:30 PM IST","hoursNote":"Sunday: Reserved for Bridal Deliveries & Trials","phoneLabel":"Direct Phone & Inquiry","phone":"+91 98230 45679 / +91 20 2544 1289","tel":"+919823045679","instagramLabel":"Instagram Community","instagram":"@ananyacreations.boutique","waCta":"Instant WhatsApp Chat","callCta":"Call Artisan"}', '2026-10-28T15:03:24.389Z');
INSERT OR REPLACE INTO site_settings (id, key, value, updated_at) VALUES ('footer', 'footer', '{"desc":"Preserving timeless Marathi craftsmanship through handcrafted heirloom Kolhapuri Saaj, Paithani-matched ornaments and ceremonial floral jewellery.","badges":["Authenticity Guarantee","International Shipping","Private Concierge"],"curationsTitle":"Curations","curations":["Heirloom Kolhapuri Saaj","Peshwai & Tanmani Sets","Haldi Floral & Pearl Ornaments","Bridal Sakharpuda Suites","Artisan Custom Atelier"],"hoursTitle":"Boutique Hours","hours":[{"text":"Tuesday – Sunday:","strong":"10:30 AM – 8:00 PM IST"},{"text":"Monday Atelier Consultations:","strong":"Prior Appointment Only"}],"hoursNote":"Bridal trials require 48h advance reservation.","contactTitle":"Atelier Contact","address":"Laxmi Road Heritage Quarter, Pune, Maharashtra 411030","phones":["+91 98230 45678 / +91 20 2445 8900","+91 98230 45679 (Artisan WhatsApp)"],"waCta":"WhatsApp Tai","copyright":"© 2025 Ratnāvali Maharashtrian Handcrafted Fine Atelier. All rights reserved."}', '2026-10-28T15:03:24.389Z');
